from fractions import Fraction


def compare(left, right):
    """Return -1, 0, or 1 according to the values of two (n, d) pairs."""
    a, b = left
    c, d = right
    if b == 0 or d == 0:
        raise ValueError("denominator must be nonzero")

    # Normalize local variables; the original pairs remain unchanged.
    if b < 0:
        a, b = -a, -b
    if d < 0:
        c, d = -c, -d
    x, y = a * d, c * b
    return (x > y) - (x < y)


def verify():
    pairs = [(n, d) for n in range(-3, 4)
             for d in range(-3, 4) if d != 0]
    for left in pairs:
        for right in pairs:
            a, b = Fraction(*left), Fraction(*right)
            expected = (a > b) - (a < b)
            assert compare(left, right) == expected, (left, right)

    assert compare((1, -2), (-2, 4)) == 0  # Equal values, distinct pairs.
    assert compare((1, 2), (1, -3)) == 1   # Opposite denominator signs.
    for left, right in [((1, 0), (1, 2)), ((1, 2), (1, 0))]:
        try:
            compare(left, right)
        except ValueError:
            pass
        else:
            raise AssertionError("zero denominator was accepted")
    print(f"Verified {len(pairs) ** 2} comparisons and zero-denominator rejection.")


if __name__ == "__main__":
    verify()
