from collections import Counter
from fractions import Fraction
from itertools import permutations


def main():
    tokens = ("R1", "R2", "R3", "B1", "B2")
    draws = list(permutations(tokens, 2))
    groups = {sequence: [] for sequence in ("RR", "RB", "BR", "BB")}
    for draw in draws:
        sequence = draw[0][0] + draw[1][0]
        groups[sequence].append(draw)

    counts = Counter({sequence: len(group) for sequence, group in groups.items()})
    assert len(draws) == 20
    assert counts == {"RR": 6, "RB": 6, "BR": 6, "BB": 2}
    for sequence, group in groups.items():
        print(f"{sequence}: {group}; P = {Fraction(len(group), len(draws))}")

    both_red = {draw for draw in draws if all(t.startswith("R") for t in draw)}
    at_least_one_red = {draw for draw in draws if any(t.startswith("R") for t in draw)}
    first_red = {draw for draw in draws if draw[0].startswith("R")}

    given_any = Fraction(len(both_red & at_least_one_red), len(at_least_one_red))
    given_first = Fraction(len(both_red & first_red), len(first_red))
    assert given_any == Fraction(1, 3)
    assert given_first == Fraction(1, 2)
    print(f"P(both red | at least one red) = {given_any}")
    print(f"P(both red | first red) = {given_first}")


if __name__ == "__main__":
    main()
```

