def every_reader_has_a_book(readers, books, read):
    return all(any((r, b) in read for b in books) for r in readers)


def some_book_read_by_every_reader(readers, books, read):
    return any(all((r, b) in read for r in readers) for b in books)


readers = ("Ira", "Sol", "Uma")
books = ("Alder", "Birch", "Cedar", "Dogwood")
read = {
    ("Ira", "Alder"), ("Ira", "Birch"),
    ("Sol", "Birch"), ("Sol", "Cedar"),
    ("Uma", "Cedar"), ("Uma", "Dogwood"),
}

cases = [
    ("table", readers, books, (True, False)),
    ("empty readers", (), books, (True, True)),
    ("empty books", readers, (), (False, False)),
    ("both empty", (), (), (True, False)),
]
for name, rs, bs, expected in cases:
    each = every_reader_has_a_book(rs, bs, read)
    common = some_book_read_by_every_reader(rs, bs, read)
    assert (each, common) == expected
    assert not common or each  # Reverse implication.
    print(f"{name}: each={each}, common={common}")
```

`all` over an empty collection is true, while `any` over one is false. With no readers, the per-reader statement is vacuously true; the common-book statement still needs a book to exist. With readers but no books, both fail. In every case, a common book implies that each reader has a book; the converse fails on the supplied table.
